cat > "$TK_SRC/preset.json" <<'TOKEN_KIT_PRESET'
{
  "profiles": [
    {
      "name": "bz-studio",
      "match": "^python3?\\s+(?:studio/)?bz/\\w+\\.py\\b",
      "keep": [
        "\\bERRO\\b|\\bFALHA\\b|Traceback|Error|Exception",
        "peças-camada|^casos \\d+ falhas",
        "\\.(?:mp4|png|jpg)$|_legenda\\.txt$"
      ],
      "drop": [
        "^frame=\\s*\\d+",
        "^\\s*\\d{1,3}%\\|"
      ],
      "tail": 12
    },
    {
      "name": "bz-studio-render",
      "match": "^python3?\\s+(?:studio/)?(?:render|export|export_m|sheets|sheets_m|avatars|duo)\\.py\\b",
      "keep": [
        "Traceback|Error|Exception|\\bERRO\\b|\\bFALHA\\b",
        "\\.(?:mp4|png|jpg|webp)$"
      ],
      "drop": [
        "^frame=\\s*\\d+",
        "^\\s*\\d{1,3}%\\|"
      ],
      "tail": 12
    }
  ]
}
TOKEN_KIT_PRESET
tar xzf "$TK_SRC/kit.tgz" -C "$TK_SRC" && node "$TK_SRC/bin/tk.mjs" install --claude-md --effort low --subagent-model sonnet --vault /home/user/vault --config "$TK_SRC/preset.json" || echo "token-kit: install failed" >&2
# RTK (optional): pinned version because the GitHub API often refuses the latest-version lookup during setup
if ! command -v rtk >/dev/null 2>&1; then
  (curl -fsSL https://raw.githubusercontent.com/rtk-ai/rtk/refs/heads/master/install.sh | RTK_VERSION=v1.0.1 sh) >/dev/null 2>&1 \
    && ln -sf "$HOME/.local/bin/rtk" /usr/local/bin/rtk 2>/dev/null || echo "token-kit: RTK not installed (the kit works without it)" >&2
fi
rm -rf "$TK_SRC"
exit 0
